         // \u5B9A\u4E49\u4F20\u611F\u5668\u5F15\u811A\n#define DHTTYPE DHT20        // \u4F7F\u7528 DHT 20 \u7C7B\u578B\nDHT dht(DHTTYPE);            // \u521D\u59CB\u5316\u6E29\u6E7F\u5EA6 DHT \u4F20\u611F\u5668\n\n// \u53D1\u9001 AT \u547D\u4EE4\u5E76\u5728\u8D85\u65F6\u65F6\u95F4\u5185\u68C0\u67E5\u9884\u671F\u54CD\u5E94\u7684\u51FD\u6570\nstatic int at_send_check_response(char *expected_ack, int timeout_ms, char *command_format, ...) {\n    int character;\n    int num = 0;\n    int index = 0;\n    int startMillis = 0;\n    va_list args;\n    memset(recv_buf, 0, sizeof(recv_buf));\n    va_start(args, command_format);\n    Serial1.printf(command_format, args);\n    Serial.printf(command_format, args);\n    va_end(args);\n    delay(200);\n    startMillis = millis();\n\n    if (expected_ack == NULL) {\n        return 0;\n    }\n\n    do {\n        while (Serial1.available() > 0) {\n            character = Serial1.read();\n            recv_buf[index++] = character;\n            Serial.print((char)character);\n            delay(2);\n        }\n\n        if (strstr(recv_buf, expected_ack) != NULL) {\n            return 1;\n        }\n    } while (millis() - startMillis < timeout_ms);\n    return 0;\n}\n\n// \u89E3\u6790\u63A5\u6536\u6D88\u606F\u7684\u51FD\u6570\nstatic void recv_parse(char *message) {\n    if (message == NULL) {\n        return;\n    }\n    char *start = NULL;\n    int data = 0;\n    int rssi = 0;\n    int snr = 0;\n\n    start = strstr(message, "RX");\n    if (start && (1 == sscanf(start, "RX: \\"%d\\"\\r\\n", &data))) {\n        Serial.println(data);\n        Serial.print("led :");\n        led = !!data;\n        Serial.println(led);\n        digitalWrite(LED_BUILTIN, led ? LOW : HIGH);\n    }\n\n    start = strstr(message, "RSSI");\n    if (start && (1 == sscanf(start, "RSSI %d,", &rssi))) {\n        Serial.print("RSSI:");\n        Serial.println(rssi);\n    }\n    \n    start = strstr(message, "SNR");\n    if (start && (1 == sscanf(start, "SNR %d", &snr))) {\n        Serial.print("SNR :");\n        Serial.println(snr);\n    }\n}\n\nvoid setup() {\n    Serial.begin(115200); // \u521D\u59CB\u5316\u4E32\u53E3\u901A\u4FE1\n    Serial1.begin(9600, SERIAL_8N1, 44, 43);\n    Wire.begin();\n    dht.begin();\n\n    // \u57FA\u672C AT \u547D\u4EE4\u68C0\u67E5\u6A21\u5757\u662F\u5426\u5B58\u5728\n    if (at_send_check_response("+AT: OK", 100, "AT\\r\\n")) {\n        is_exist = true;\n\n        // \u53D1\u9001 AT+ID \u547D\u4EE4\u83B7\u53D6\u8BBE\u5907 ID\n        if (at_send_check_response("+ID:", 1000, "AT+ID\\r\\n")) {\n            Serial.print("Received ID data: ");\n            Serial.println(recv_buf);\n        } else {\n            Serial.println("Failed to get ID data.");\n        }\n\n        // \u5176\u4ED6\u914D\u7F6E\u547D\u4EE4\n        at_send_check_response("+MODE: LWOTAA", 1000, "AT+MODE=LWOTAA\\r\\n");\n        at_send_check_response("+DR: EU868", 1000, "AT+DR=EU868\\r\\n");\n        at_send_check_response("+CH: NUM", 1000, "AT+CH=NUM,0-2\\r\\n");\n        at_send_check_response("+KEY: APPKEY", 1000, "AT+KEY=APPKEY,\\"2B7E151628AED2A6ABF7158809CF4F3D\\"\\r\\n");\n        at_send_check_response("+CLASS: C", 1000, "AT+CLASS=A\\r\\n");\n        at_send_check_response("+PORT: 8", 1000, "AT+PORT=8\\r\\n");\n        \n        delay(200);\n        is_join = true;\n    } else {\n        is_exist = false;\n        Serial.println("No E5 module found.");\n    }\n}\n\nvoid loop() {\n    float temp_hum_val[2] = {0};\n    if (is_exist) {\n        int ret = 0;\n        if (is_join) {\n            ret = at_send_check_response("+JOIN: Network joined", 12000, "AT+JOIN\\r\\n");\n            if (ret) {\n                is_join = false;\n            } else {\n                at_send_check_response("+ID: AppEui", 1000, "AT+ID\\r\\n");\n                Serial.println("JOIN failed!");\n                delay(5000);\n            }\n        } else {\n            if (!dht.readTempAndHumidity(temp_hum_val)) {\n                char cmd[128];\n                sprintf(cmd, "AT+CMSGHEX=\\"%04X%04X%04X\\"\\r\\n", int(temp_hum_val[1] * 100), int(temp_hum_val[0] * 100), analogRead(sensorPin));\n                ret = at_send_check_response("Done", 5000, cmd);\n                if (ret) {\n                    recv_parse(recv_buf);\n                } else {\n                    Serial.println("Send failed!");\n                }\n            }\n            delay(30000);\n        }\n    } else {\n        delay(1000);\n    }\n}\n'})}),"\n",(0,i.jsx)(n.h3,{id:"chirpstack-\u914D\u7F6E",children:"ChirpStack \u914D\u7F6E"}),"\n",(0,i.jsxs)(n.p,{children:["ChirpStack \u662F\u4E00\u4E2A\u5F00\u6E90\u7684\u7269\u8054\u7F51\uFF08IoT\uFF09\u89E3\u51B3\u65B9\u6848\uFF0C\u4E13\u4E3A\u6784\u5EFA\u548C\u7BA1\u7406 LoRaWAN \u7F51\u7EDC\u800C\u8BBE\u8BA1\u3002\u5B83\u63D0\u4F9B\u4E86\u4E00\u5957\u5168\u9762\u7684\u5DE5\u5177\u548C\u670D\u52A1\uFF0C\u5E2E\u52A9\u7528\u6237\u90E8\u7F72\u3001\u7BA1\u7406\u548C\u76D1\u63A7 LoRaWAN \u7F51\u7EDC\uFF0C\u5305\u62EC\u7F51\u5173\u3001\u7F51\u7EDC\u670D\u52A1\u5668\u3001\u5E94\u7528\u670D\u52A1\u5668\u548C\u8BBE\u5907\u3002\u6709\u5173\u5982\u4F55\u8FDE\u63A5\u5230 ChirpStack \u7684\u4FE1\u606F\uFF0C\u8BF7\u53C2\u8003\u6B64",(0,i.jsx)(n.a,{href:"https://wiki.seeedstudio.com/cn/Network/SenseCAP_Network/SenseCAP_M2_Multi_Platform/Tutorial/Connect-M2-Multi-Platform-Gateway-to-ChirpStack/#chirpstack-configuration",children:"\u94FE\u63A5"}),"\u3002"]}),"\n",(0,i.jsx)(n.p,{children:"\u5728 ChirpStack \u4E2D\u521B\u5EFA\u65B0\u7684\u8BBE\u5907\u914D\u7F6E\u6587\u4EF6\u540E\uFF0C\u4F7F\u7528\u4EE5\u4E0B\u4EE3\u7801\u586B\u5199\u6709\u6548\u8F7D\u8377\u7F16\u89E3\u7801\u5668\uFF1A"}),"\n",(0,i.jsx)(n.pre,{children:(0,i.jsx)(n.code,{className:"language-js",children:'function decodeUplink(input) {\n  var decoded = {\n    temp: 0,\n    humi: 0,\n    moisture: 0,\n  };\n  var bytes = input["bytes"];\n  bytes = bytes2HexString(bytes);\n\n  // Assuming the data is encoded at a ratio of 100 times\n  decoded.temp = parseInt(bytes.slice(0, 4), 16) / 100;\n  decoded.humi = parseInt(bytes.slice(4, 8), 16) / 100;\n  decoded.moisture = parseInt(bytes.slice(-4), 16);\n\n  let messages = [\n    {\n      type: "temp",\n      measurementId: 4097,\n      measurementValue: decoded.temp,\n    },\n    {\n      type: "humi",\n      measurementId: 4098,\n      measurementValue: decoded.humi,\n    },\n    {\n      type: "moisture",\n      measurementId: 4103,\n      measurementValue: decoded.moisture,\n    },\n  ];\n\n  var result = {};\n  result.messages = messages;\n  return { data: result };\n}\n\n/**\n * Convert to an 8-digit binary number with 0s in front of the number\n * @param arr\n * @returns {string}\n */\nfunction toBinary(arr) {\n  let binaryData = arr.map((item) => {\n    let data = parseInt(item, 16).toString(2);\n    let dataLength = data.length;\n    if (data.length !== 8) {\n      for (let i = 0; i < 8 - dataLength; i++) {\n        data = `0` + data;\n      }\n    }\n    return data;\n  });\n  let ret = binaryData.toString().replace(/,/g, "");\n  return ret;\n}\n\nfunction bytes2HexString(arrBytes) {\n  var str = "";\n  for (var i = 0; i < arrBytes.length; i++) {\n    var tmp;\n    var num = arrBytes[i];\n    if (num < 0) {\n      tmp = (255 + num + 1).toString(16);\n    } else {\n      tmp = num.toString(16);\n    }\n    if (tmp.length === 1) {\n      tmp = "0" + tmp;\n    }\n    str += tmp;\n  }\n  return str;\n}\n'})}),"\n",(0,i.jsxs)(n.h4,{id:"\u70B9\u51FB-submit",children:["\u70B9\u51FB ",(0,i.jsx)(n.strong,{children:"Submit"}),"\u3002"]}),"\n",(0,i.jsx)("div",{align:"center",children:(0,i.jsx)("img",{width:800,src:"https://files.seeedstudio.com/wiki/Grove-Wio-E5_with_XIAO-ESP32-S3_via_Arduino/image4.png"})}),"\n",(0,i.jsx)(n.p,{children:"\u5982\u4E0B\u56FE\u6240\u793A\uFF0C\u63A5\u6536\u5230\u76F8\u5173\u6570\u636E\uFF0C\u8868\u660E\u6570\u636E\u53D1\u9001\u6210\u529F\u3002"}),"\n",(0,i.jsx)("div",{align:"center",children:(0,i.jsx)("img",{width:800,src